import jax.numpy as jnp

def solve(initial, target, rate, tolerance, limit):
    def body(_, carry):
        state, steps = carry
        stopped = (steps >= limit) | (jnp.abs(target - state) <= tolerance)
        return jax.lax.cond(
            stopped,
            lambda carry: carry,
            lambda carry: (
                carry[0] + rate * (target - carry[0]), carry[1] + 1
            ),
            carry,
        )

    # A static bound lowers to scan, allowing reverse-mode differentiation.
    # The conditional preserves the dynamic stopping decision and step count.
    return jax.lax.fori_loop(0, 16, body, (initial, jnp.int32(0)))
